class Reader {
    private String readerID;
    private String name;
    private int booksBorrowed;
    private String membershipType;

    public Reader(String id, String name, int books, String type) {
        this.readerID = id;
        this.name = name;
        this.booksBorrowed = books;
        this.membershipType = type;
    }

    public String getReaderID() { return readerID; }
    public String getName() { return name; }
    public int getBooksBorrowed() { return booksBorrowed; }
    public String getMembershipType() { return membershipType; }

    public int getMembershipPoints() {
        if (membershipType.equalsIgnoreCase("Gold")) return 30;
        if (membershipType.equalsIgnoreCase("Silver")) return 20;
        return 10;
    }

    public int calculateScore() {
        return (booksBorrowed * 5) + getMembershipPoints();
    }

    public boolean checkEligibility() {
        RecommendationEngine engine = new RecommendationEngine();
        return engine.eligible(this);
    }
}

class RecommendationEngine {
    public boolean eligible(Reader r) {
        int points = r.getMembershipPoints();
        int score = (r.getBooksBorrowed() * 5) + points;
        return score >= 80;
    }
}
```

