public static double calculateAverageMileage(Truck[] trucks) {
    if (trucks == null || trucks.length == 0) return 0.0;
    double totalMileage = 0;
    for (Truck t : trucks) {
        totalMileage += t.getDistance() / t.getFuel();
    }
    return totalMileage / trucks.length;
}
