public static void printStats(Truck[] trucks) {
    double totalMileage = 0;
    int excellent = 0, good = 0, average = 0, poor = 0;
    for (Truck t : trucks) {
        double m = t.getDistance() / t.getFuel();
        totalMileage += m;
        if (m >= 18) excellent++;
        else if (m >= 15) good++;
        else if (m >= 10) average++;
        else poor++;
    }
    System.out.println("Average Mileage: " + (totalMileage / trucks.length));
    System.out.println("Categories - Excellent: " + excellent + ", Good: " + good + ", Average: " + average + ", Poor: " + poor);
}
```

