class Passenger {
    private String passengerId;
    private String airlineName;
    private double baggageWeight;
    private static double freeAllowance;

    static {
        freeAllowance = 20.0;
    }

    public Passenger(String id, String airline, double weight) {
        this.passengerId = id;
        this.airlineName = airline;
        this.baggageWeight = weight;
    }

    public double calculateExcessCharge() {
        if (baggageWeight > freeAllowance) {
            return (baggageWeight - freeAllowance) * 500;
        }
        return 0;
    }

    public static void setFreeAllowance(double allowance) {
        freeAllowance = allowance;
    }

    public String getId() {
        return passengerId;
    }
}
```
