```java
public class CarbonFootprint {
    public static void main(String[] args) {
        double miles = 50.0;
        double kwh = 100.0;
        double waste = 10.0;
        int recycled = 1;
        int publicTransport = 1;

        double vehicleEmission = miles * 0.40;
        double electricityEmission = kwh * 0.85;
        double wasteEmission = waste * 1.20;
        double total = vehicleEmission + electricityEmission + wasteEmission;

        boolean isLessThan20 = total < 20;
        boolean isEcoFriendly = isLessThan20 && (recycled == 1) && (publicTransport == 1);

        System.out.println("Vehicle Emission: " + vehicleEmission);
        System.out.println("Electricity Emission: " + electricityEmission);
        System.out.println("Waste Emission: " + wasteEmission);
        System.out.println("Total Footprint: " + total);
        System.out.println("Under 20: " + isLessThan20);
        System.out.println("Eco-Friendly: " + isEcoFriendly);
    }
}
```

