    bonus = 0;
}

if (currentScore < 200) level = "Beginner";
else if (currentScore < 400) level = "Intermediate";
else if (currentScore < 700) level = "Advanced";
else level = "Master";

if (coins >= 50) {
    System.out.println("Extra Life Awarded!");
} else {
    System.out.println("Keep Collecting Coins!");
}
System.out.println("Score: " + currentScore + ", Bonus: " + bonus + ", Level: " + level);
