Here is the complete JavaScript code to calculate the total revenue, individual amounts, and find the highest-paying vehicle handling ties:

```javascript
let totalRevenue = 0;
let maxAmount = -1;
let highestVehicle = '';

for (let session of sessions) {
  let rate = session.vehicleType === 'Car' ? 20 : session.vehicleType === 'Bike' ? 10 : 30;
  let amount = session.energy * rate;
  totalRevenue += amount;

  if (amount > maxAmount) {
    maxAmount = amount;
    highestVehicle = session.vehicleNumber;
  }
}
console.log(totalRevenue, highestVehicle, maxAmount);
